from unittest.mock import patch

sys.dont_write_bytecode = True
REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO / "scripts"))
import hermes_catalog as CATALOG
import hermes_files as FILES
import hermes_profiles as PROFILES
import hermes_local as LOCAL


class ProfileLifecycle(unittest.TestCase):
    def setUp(self) -> None:
        self.previous_umask = os.umask(0o077)
        self.temporary = tempfile.TemporaryDirectory(prefix="godseye-hermes-profiles-")
        self.root = Path(self.temporary.name).resolve()
        self.workspace = self.root / "workspace"
        self.workspace.mkdir(mode=0o700)
        shutil.copytree(REPO / "infra/hermes", self.workspace / "infra/hermes")
        self.profiles = self.root / "profiles"
        self.profiles.mkdir(mode=0o700)
        self.input = {
            "projectId": "11111111-1111-4111-8111-111111111111",
            "environmentId": "22222222-2222-4222-8222-222222222222",
            "role": "operations",
        }

    def tearDown(self) -> None:
        self.temporary.cleanup()
        os.umask(self.previous_umask)

    def prepare(self, **changes: object) -> dict:
        with FILES.exclusive(self.profiles):
            return PROFILES.prepare(self.profiles, self.workspace, {**self.input, **changes})

    def inspect(self, record: dict) -> dict:
        return PROFILES.inspect(self.profiles, self.workspace, {"profileId": record["profileId"]})

    def promote(self, target: dict, expected: str) -> dict:
        with FILES.exclusive(self.profiles):
            return PROFILES.promote(self.profiles, self.workspace, {
                "profileId": target["profileId"], "revision": target["revision"],
                "expectedRevision": expected,
            })

    def catalog_path(self) -> Path:
        return self.workspace / "infra/hermes/catalog.json"

    def source_skill(self) -> Path:
        return self.workspace / "infra/hermes/skills/godseye-context/1.0.0/SKILL.md"

    def test_roles_and_scopes_have_distinct_homes_and_no_admitted_authority(self) -> None:
        records = []
        for index in range(3):
            for role in ("operations", "security", "research-marketing"):
                environment = str(uuid.uuid5(uuid.NAMESPACE_URL, f"fixture-environment-{index}"))
                records.append(self.prepare(role=role, environmentId=environment))
        self.assertEqual(len({item["profileId"] for item in records}), 9)
        self.assertEqual(len({item["home"] for item in records}), 9)
        for record in records:
            self.assertEqual(record["binding"], "declared-local")
            self.assertFalse(record["runEnabled"])
            self.assertFalse(record["providerConnected"])
            self.assertEqual(record["admission"], "not-qualified")
            self.assertEqual(record["homeKind"], "immutable-setup-snapshot")
            self.assertIsNone(record["runtimeHome"])
            self.assertEqual(Path(record["home"]).stat().st_mode & 0o777, 0o700)

    def test_repeated_preparation_is_deterministic_and_does_not_create_a_revision(self) -> None:
        first = self.prepare()
        before = self.inspect(first)
        second = self.prepare()
        self.assertEqual(second, first)
        self.assertEqual(self.inspect(first)["revisions"], before["revisions"])
        self.assertEqual(before["revisions"], [first["revision"]])

    def test_model_change_stages_without_changing_current_revision(self) -> None:
        first = self.prepare()
        staged = self.prepare(model="fixture-model")
        current = self.inspect(first)
        self.assertEqual(staged["profileId"], first["profileId"])
        self.assertNotEqual(staged["revision"], first["revision"])
        self.assertEqual(staged["activeRevision"], first["revision"])
        self.assertEqual(current["revision"], first["revision"])
        self.assertEqual(set(current["revisions"]), {first["revision"], staged["revision"]})

    def test_exact_promotion_and_rollback_retain_both_snapshots(self) -> None:
        first = self.prepare()
        staged = self.prepare(model="fixture-model")
        promoted = self.promote(staged, first["revision"])
        self.assertEqual(promoted["activeRevision"], staged["revision"])
        rolled_back = self.promote(first, staged["revision"])
        self.assertEqual(rolled_back["activeRevision"], first["revision"])
        self.assertEqual(set(self.inspect(first)["revisions"]), {first["revision"], staged["revision"]})
        self.assertTrue(Path(staged["home"]).is_dir())

    def test_stale_compare_and_swap_preserves_the_current_revision(self) -> None:
        first = self.prepare()
        staged = self.prepare(model="fixture-model")
        self.promote(staged, first["revision"])
        pointer = self.profiles / first["profileId"] / "active.json"
        before = pointer.read_bytes()
        with self.assertRaisesRegex(RuntimeError, "changed"):
            self.promote(first, first["revision"])
        self.assertEqual(pointer.read_bytes(), before)

    def test_unconfigured_model_remains_unconnected_and_has_no_tools_or_learning(self) -> None:
        record = self.prepare()
        config = json.loads((Path(record["home"]) / "config.yaml").read_bytes())
        self.assertEqual(config["model"], {"provider": "openai", "default": "UNCONFIGURED"})
        self.assertEqual(config["platform_toolsets"], {"cli": [], "api_server": []})
        self.assertFalse(config["curator"]["enabled"])
        self.assertFalse(config["skills"]["project_discovery"])
        self.assertEqual(config["skills"]["external_dirs"], [])
        self.assertEqual(config["mcp_servers"], {})
        self.assertTrue((Path(record["home"]) / ".no-bundled-skills").is_file())
        self.assertEqual(record["skills"], [{"id": "godseye-context", "version": "1.0.0"}])

    def test_invalid_scope_role_and_model_inputs_do_not_publish_profiles(self) -> None:
        malformed = [
            {"projectId": "../other"}, {"projectId": 123}, {"projectId": ""},
            {"environmentId": "22222222-2222-4222-8222-22222222222Z"},
            {"environmentId": None}, {"role": "admin"}, {"role": "../security"},
            {"role": ["security"]}, {"model": "../model"}, {"model": "a\nrun"},
            {"model": "$(echo x)"}, {"model": "x" * 129}, {"model": {}},
        ]
        for change in malformed:
            with self.subTest(change=change):
                with self.assertRaises((ValueError, TypeError, AttributeError)):
                    self.prepare(**change)
        self.assertEqual(PROFILES.list_entries(self.profiles), [])

    def test_modified_catalog_skill_is_refused_before_profile_publication(self) -> None:
        self.source_skill().write_bytes(self.source_skill().read_bytes() + b"\nUnreviewed changed instructions.\n")
        with self.assertRaises(ValueError):
            self.prepare()
        self.assertEqual(PROFILES.list_entries(self.profiles), [])

    def test_unreviewed_catalog_file_is_refused(self) -> None:
        (self.source_skill().parent / "unexpected.md").write_bytes(b"unreviewed")
        with self.assertRaisesRegex(ValueError, "unreviewed"):
            self.prepare()
        self.assertEqual(PROFILES.list_entries(self.profiles), [])

    def test_linked_catalog_skill_is_refused_without_following_it(self) -> None:
        path = self.source_skill()
        outside = self.root / "outside.md"
        outside.write_bytes(path.read_bytes())
        path.unlink()
        path.symlink_to(outside)
        with self.assertRaises((ValueError, RuntimeError)):
            self.prepare()
        self.assertEqual(PROFILES.list_entries(self.profiles), [])

    def test_hardlinked_catalog_skill_is_refused(self) -> None:
        os.link(self.source_skill(), self.root / "alias.md")
        with self.assertRaises(RuntimeError):
            self.prepare()
        self.assertEqual(PROFILES.list_entries(self.profiles), [])

    def test_catalog_version_provenance_paths_and_duplicate_ids_are_rejected(self) -> None:
        path = self.catalog_path()
        original = json.loads(path.read_bytes())
        changes = [
            ("version", "latest"), ("version", "01.0.0"),
            ("provenance", "community:unreviewed"), ("hermesVersion", "0.0.0"),
            ("files", {"../outside.md": "0" * 64}),
            ("files", {"SKILL.md": "not-a-hash"}),
        ]
        for key, value in changes:
            changed = json.loads(json.dumps(original))
            changed["skills"][0][key] = value
            path.write_text(json.dumps(changed))
            with self.subTest(key=key, value=value):
                with self.assertRaises(ValueError):
                    CATALOG.catalog(self.workspace)
        duplicate = json.loads(json.dumps(original))
        duplicate["skills"].append(duplicate["skills"][0])
        path.write_text(json.dumps(duplicate))
        with self.assertRaises(ValueError):
            CATALOG.catalog(self.workspace)

    def test_retained_snapshot_remains_inspectable_when_current_catalog_changes(self) -> None:
        first = self.prepare()
        self.source_skill().write_bytes(b"unreviewed changed source")
        inspected = self.inspect(first)
        self.assertEqual(inspected["revision"], first["revision"])
        with self.assertRaises(ValueError):
            self.prepare()

