    def test_profile_capacity_refusal_preserves_existing_profile(self) -> None:
        first = self.prepare()
        with patch.object(PROFILES, "MAX_PROFILES", 1):
            with self.assertRaisesRegex(RuntimeError, "capacity"):
                self.prepare(role="security")
        self.assertEqual(self.inspect(first)["revision"], first["revision"])

    def test_missing_promotion_revision_does_not_change_active_state(self) -> None:
        first = self.prepare()
        before = self.inspect(first)
        missing = {**first, "revision": "f" * 64}
        with self.assertRaises((RuntimeError, FileNotFoundError)):
            self.promote(missing, first["revision"])
        self.assertEqual(self.inspect(first)["activeRevision"], before["activeRevision"])

    def test_public_dispatch_rejects_unknown_fields_and_runner_actions_before_writing(self) -> None:
        managed = self.root / "managed"
        invalid = [
            {"action": "chat"}, {"action": "run"}, {"action": "serve"},
            {"action": "prepare", **self.input, "grant": "owner"},
            {"action": "prepare", **self.input, "tools": ["terminal"]},
            {"action": "profiles", "directory": "/outside"},
            {"action": "catalog", "provider": "anthropic"},
        ]
        with patch.object(LOCAL, "runtime_root", return_value=managed):
            for payload in invalid:
                with self.subTest(payload=payload):
                    with self.assertRaises(ValueError):
                        LOCAL.execute({"workspace": str(self.workspace), **payload})
        self.assertFalse(managed.exists())

    def test_public_dispatch_prepares_lists_and_verifies_without_runner_authority(self) -> None:
        managed = self.root / "managed"
        with patch.object(LOCAL, "runtime_root", return_value=managed):
            record = LOCAL.execute({"workspace": str(self.workspace), "action": "prepare", **self.input})
            listed = LOCAL.execute({"workspace": str(self.workspace), "action": "profiles"})
            verified = LOCAL.execute({"workspace": str(self.workspace), "action": "verify", "profileId": record["profileId"]})
        self.assertEqual([item["profileId"] for item in listed["profiles"]], [record["profileId"]])
        self.assertFalse(listed["runEnabled"])
        self.assertTrue(verified["verified"])
        self.assertFalse(verified["runEnabled"])
        self.assertEqual(verified["binding"], "declared-local")

    def test_public_dispatch_refuses_foreign_workspace_marker_without_rebinding(self) -> None:
        managed = self.root / "managed"
        with patch.object(LOCAL, "runtime_root", return_value=managed):
            LOCAL.execute({"workspace": str(self.workspace), "action": "profiles"})
            marker = managed / ".godseye-hermes.json"
            changed = json.loads(marker.read_bytes())
            changed["workspace"] = "/fixture-foreign-workspace"
            marker.write_text(json.dumps(changed))
            before = marker.read_bytes()
            with self.assertRaisesRegex(RuntimeError, "ownership differs"):
                LOCAL.execute({"workspace": str(self.workspace), "action": "profiles"})
        self.assertEqual(marker.read_bytes(), before)

    def test_public_dispatch_refuses_unmarked_nonempty_runtime_without_adoption(self) -> None:
        managed = self.root / "managed"
        managed.mkdir(mode=0o700)
        sentinel = managed / "retained.txt"
        sentinel.write_bytes(b"fixture foreign state")
        with patch.object(LOCAL, "runtime_root", return_value=managed):
            with self.assertRaisesRegex(RuntimeError, "Unmarked"):
                LOCAL.execute({"workspace": str(self.workspace), "action": "profiles"})
        self.assertEqual(sentinel.read_bytes(), b"fixture foreign state")
        self.assertFalse((managed / ".godseye-hermes.json").exists())

    def test_missing_profile_inspection_does_not_create_an_invalid_profile(self) -> None:
        managed = self.root / "managed"
        missing = "44444444-4444-4444-8444-444444444444"
        with patch.object(LOCAL, "runtime_root", return_value=managed):
            LOCAL.execute({"workspace": str(self.workspace), "action": "profiles"})
            with self.assertRaises((FileNotFoundError, RuntimeError)):
                LOCAL.execute({"workspace": str(self.workspace), "action": "inspect", "profileId": missing})
            listed = LOCAL.execute({"workspace": str(self.workspace), "action": "profiles"})
        self.assertEqual(listed["profiles"], [])
        self.assertFalse((managed / "profiles" / missing).exists())


